const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const s = input[0];
const n = Number(input[1]);
const len = s.length;

function check(a) {
    for (let i = 1; i <= a - n; i++) {
        if (s[len - i] !== s[len - i - a]) {
            return false;
        }
    }
    return true;
}

let ans = 0;
let temp = 0;

const min = n > len ? Math.trunc((len + n) / 2) : n;
const max = Math.trunc((len + n) / 2);

for (let i = 0; i < len; i++) {
    for (let j = 1; j * 2 + i <= len; j++) {
        let key = true;
        for (let k = 1; k <= j; k++) {
            if (s[i + k - 1] !== s[i + k + j - 1]) {
                key = false;
            }
        }
        if (key && j > temp) {
            temp = j;
        }
    }
}

for (let i = max; i >= min && ans === 0; i--) {
    if (check(i)) {
        ans = i;
    }
}

if (min > ans) {
    ans = min;
}
if (temp > ans) {
    ans = temp;
}

process.stdout.write(String(2 * ans));

